1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID     string `json:"id"`
27		Name   string `json:"name"`
28		Price  int64  `json:"price_fen"`         // 固定单价，非负整数分，创建后不可修改
29		PlanID string `json:"plan_id,omitempty"` // 绑定的阶梯计费方案标识；空表示固定单价客户，创建后不可变更
30	}
31	
32	// tier 是阶梯计费方案中的一档：Limit 为月累计数量上限（正整数），
33	// 仅最后一档无上限（Limit 为 0）；Price 为该档每单位价格（非负整数分）。
34	type tier struct {
35		Limit int64 `json:"limit"`     // 累计数量上限；0 表示无上限（仅最后一档）
36		Price int64 `json:"price_fen"` // 每单位价格，非负整数分，可升可降
37	}
38	
39	// plan 是按月累计用量的阶梯计费方案：标识唯一非空、名称非空、固定月费
40	// （非负整数分，省略视为 0）与至少一档有序阶梯；月费与规则创建后不可修改。
41	type plan struct {
42		ID         string `json:"id"`
43		Name       string `json:"name"`
44		MonthlyFee int64  `json:"monthly_fee_fen,omitempty"` // 固定月费，非负整数分；每账期收取一次整月，不按天折算
45		Tiers      []tier `json:"tiers"`                     // 至少一档；有限上限严格递增，最后一档无上限
46	}
47	
48	type usageRecord struct {
49		ID         string `json:"id"`
50		CustomerID string `json:"customer_id"`
51		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
52		Quantity   int64  `json:"quantity"`
53	}
54	
55	// lineSegment 是阶梯计费下一条用量记录落入某一档的分段：数量与小计；
56	// 该档单价由账单保存的方案规则按档位序号取得。
57	type lineSegment struct {
58		Tier     int   `json:"tier"`     // 档位序号（0 起，对应账单保存的方案规则）
59		Quantity int64 `json:"quantity"` // 落入本档的数量
60		Fee      int64 `json:"fee_fen"`  // 本分段小计（数量 × 该档单价）
61	}
62	
63	// tierTotal 是阶梯账单中某一档的合计数量与金额（与 PlanTiers 顺序对齐）。
64	type tierTotal struct {
65		Quantity int64 `json:"quantity"`
66		Fee      int64 `json:"fee_fen"`
67	}
68	
69	type billLine struct {
70		UsageID  string        `json:"usage_id"`
71		Time     string        `json:"time"`
72		Quantity int64         `json:"quantity"`
73		LineFee  int64         `json:"line_fee_fen"`
74		Segments []lineSegment `json:"segments,omitempty"` // 阶梯账单：本条用量的跨档分段
75	}
76	
77	type bill struct {
78		ID         string      `json:"id"`
79		CustomerID string      `json:"customer_id"`
80		Month      string      `json:"month"`                 // YYYY-MM（UTC）
81		Pricing    string      `json:"pricing,omitempty"`     // 计价类型：空或 fixed 为固定单价；tiered 为阶梯计费
82		PlanID     string      `json:"plan_id,omitempty"`     // 阶梯账单：方案标识
83		PlanName   string      `json:"plan_name,omitempty"`   // 阶梯账单：方案名称（快照）
84		PlanTiers  []tier      `json:"plan_tiers,omitempty"`  // 阶梯账单：完整方案规则（快照）
85		TierTotals []tierTotal `json:"tier_totals,omitempty"` // 阶梯账单：各档实际数量与金额合计
86		// 阶梯账单：实际收取的固定月费快照（分），非负；按账期有效方案收取一次
87		// 整月，不计入总数量、各档金额或逐条小计。固定单价账单恒为 0。
88		MonthlyFee int64      `json:"monthly_fee_fen,omitempty"`
89		TotalQty   int64      `json:"total_quantity"`
90		UnitPrice  int64      `json:"unit_price_fen"` // 固定单价账单的单价；阶梯账单恒为 0（不伪造统一单价）
91		TotalFee   int64      `json:"total_fee_fen"`
92		Lines      []billLine `json:"lines"`
93		CreatedAt  string     `json:"created_at"`
94	}
95	
96	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
97	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
98	type adjustment struct {
99		ID           string `json:"id"`
100		CustomerID   string `json:"customer_id"`
101		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
102		Amount       int64  `json:"amount_fen"`
103		Reason       string `json:"reason"`
104		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
105		CreatedAt    string `json:"created_at"`
106		Revoked      bool   `json:"revoked"`
107		RevokeReason string `json:"revoke_reason,omitempty"`
108		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
109		RevokedAt    string `json:"revoked_at,omitempty"`
110	}
111	
112	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
113	type paymentAllocation struct {
114		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
115		Amount int64  `json:"amount_fen"` // 正整数分
116	}
117	
118	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
119	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
120	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
121	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
122	type payment struct {
123		ID           string              `json:"id"`
124		CustomerID   string              `json:"customer_id"`
125		Total        int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
126		Note         string              `json:"note"`
127		Allocations  []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
128		Seq          int64               `json:"seq"`         // 全局递增操作序号，决定历史展示顺序
129		CreatedAt    string              `json:"created_at"`
130		Revoked      bool                `json:"revoked"`
131		RevokeReason string              `json:"revoke_reason,omitempty"`
132		RevokeSeq    int64               `json:"revoke_seq,omitempty"`
133		RevokedAt    string              `json:"revoked_at,omitempty"`
134	}
135	
136	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
137	// 读入时归一化为一项分配，之后一律按新格式写回。
138	func (p *payment) UnmarshalJSON(data []byte) error {
139		type plain payment // 去掉方法，避免递归
140		var raw struct {
141			plain
142			Month  string `json:"month"`      // 旧格式：所属账单月份
143			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
144		}
145		if err := json.Unmarshal(data, &raw); err != nil {
146			return err
147		}
148		*p = payment(raw.plain)
149		if len(p.Allocations) == 0 && raw.Month != "" {
150			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
151			p.Total = raw.Amount
152		}
153		return nil
154	}
155	
156	// amountFor 返回该收款在指定月份的分配金额；无分配时为 0。
157	func (p *payment) amountFor(month string) int64 {
158		for _, al := range p.Allocations {
159			if al.Month == month {
160				return al.Amount
161			}
162		}
163		return 0
164	}
165	
166	// correction 是对一笔未撤销收款的分配更正：客户、总额、备注、原账单及
167	// 应付不变，仅把该笔收款当前生效的分配整体替换为完整新分配。记录一旦写入
168	// 永不删除；首次登记内容永久保留，bill pay / bill remit 仍按原始分配判重，
169	// 更正不影响收款身份。可连续更正，每次以当时最新分配为起点。
170	type correction struct {
171		ID          string              `json:"id"`
172		PaymentID   string              `json:"payment_id"` // 目标收款标识
173		Reason      string              `json:"reason"`
174		Allocations []paymentAllocation `json:"allocations"` // 完整新分配，至少一项，月份不重复，按月份升序保存
175		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款及其撤销共用
176		CreatedAt   string              `json:"created_at"`
177	}
178	
179	// planChange 是阶梯客户的一次按月生效的方案变更：自生效月（UTC 自然月，
180	// 含）起改用目标方案，直到下一次变更；生效月之前的月份不受影响。记录一旦
181	// 写入永不修改或删除；变更不产生账后流水事件，也不占用全局操作序号。
182	type planChange struct {
183		CustomerID string `json:"customer_id"`
184		Month      string `json:"month"`   // YYYY-MM（UTC），生效月（含）
185		PlanID     string `json:"plan_id"` // 目标阶梯计费方案标识
186		Reason     string `json:"reason"`
187		CreatedAt  string `json:"created_at"`
188	}
189	
190	type state struct {
191		Version     int                     `json:"version"`
192		Customers   map[string]*customer    `json:"customers"`
193		Plans       map[string]*plan        `json:"plans"`        // 全局唯一方案标识 -> 阶梯计费方案
194		Usage       map[string]*usageRecord `json:"usage"`        // 全局唯一用量标识 -> 记录
195		Bills       map[string]*bill        `json:"bills"`        // 客户 + "|" + 月份 -> 账单
196		Adjustments map[string]*adjustment  `json:"adjustments"`  // 全局唯一调整标识 -> 记录
197		Payments    map[string]*payment     `json:"payments"`     // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
198		Corrections map[string]*correction  `json:"corrections"`  // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
199		PlanChanges map[string]*planChange  `json:"plan_changes"` // 客户 + "|" + 生效月 -> 方案变更（按生效月递增追加，不可改写）
200		NextSeq     int64                   `json:"next_seq"`     // 已分配的最大操作序号（调整/收款/更正及其撤销共用；方案变更不占用）
201		path        string                  `json:"-"`
202	}
203	
204	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
205	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
206	func loadStore(dir string) (*state, error) {
207		p := filepath.Join(dir, "state.json")
208		data, err := os.ReadFile(p)
209		if err != nil {
210			if errors.Is(err, os.ErrNotExist) {
211				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
212					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
213				}
214				return newState(p), nil
215			}
216			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
217		}
218	
219		var s state
220		dec := json.NewDecoder(bytes.NewReader(data))
221		if err := dec.Decode(&s); err != nil {
222			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
223		}
224		// 拒绝完整 JSON 之后的任何非空白内容（包括单独的 ] 或 }），避免静默
225		// 吞掉异常数据；合法尾随空白仍可读取。
226		if off := dec.InputOffset(); off < int64(len(data)) {
227			if strings.TrimSpace(string(data[off:])) != "" {
228				return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
229			}
230		}
231		if err := s.validate(); err != nil {
232			return nil, fmt.Errorf("数据文件已损坏: %w", err)
233		}
234		// 旧版本数据文件没有 plans/adjustments/payments/corrections/plan_changes/
235		// next_seq 字段：视为零方案、零调整、零实收、零更正、零方案变更。
236		if s.Plans == nil {
237			s.Plans = map[string]*plan{}
238		}
239		if s.Adjustments == nil {
240			s.Adjustments = map[string]*adjustment{}
241		}
242		if s.Payments == nil {
243			s.Payments = map[string]*payment{}
244		}
245		if s.Corrections == nil {
246			s.Corrections = map[string]*correction{}
247		}
248		if s.PlanChanges == nil {
249			s.PlanChanges = map[string]*planChange{}
250		}
251		s.path = p
252		return &s, nil
253	}
254	
255	func newState(p string) *state {
256		return &state{
257			Version:     stateVersion,
258			Customers:   map[string]*customer{},
259			Plans:       map[string]*plan{},
260			Usage:       map[string]*usageRecord{},
261			Bills:       map[string]*bill{},
262			Adjustments: map[string]*adjustment{},
263			Payments:    map[string]*payment{},
264			Corrections: map[string]*correction{},
265			PlanChanges: map[string]*planChange{},
266			path:        p,
267		}
268	}
269	
270	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
271	func (s *state) validate() error {
272		if s.Version != stateVersion {
273			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
274		}
275		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
276			return errors.New("缺少必要的数据节")
277		}
278		for id, p := range s.Plans {
279			if p == nil {
280				return fmt.Errorf("方案 %q 的数据为空", id)
281			}
282			if p.ID != id {
283				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
284			}
285			if err := validatePlanRules(p); err != nil {
286				return err
287			}
288		}
289		for id, c := range s.Customers {
290			if c == nil {
291				return fmt.Errorf("客户 %q 的数据为空", id)
292			}
293			if c.ID != id {
294				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
295			}
296			if c.ID == "" || c.Name == "" {
297				return fmt.Errorf("客户 %q 的标识或名称为空", id)
298			}
299			if c.Price < 0 {
300				return fmt.Errorf("客户 %q 单价为负", id)
301			}
302			if c.PlanID != "" {
303				if _, ok := s.Plans[c.PlanID]; !ok {
304					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
305				}
306			}
307		}
308		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
309		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
310		for key, ch := range s.PlanChanges {
311			if ch == nil {
312				return fmt.Errorf("方案变更 %q 的数据为空", key)
313			}
314			if planChangeKey(ch.CustomerID, ch.Month) != key {
315				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
316			}
317			c, ok := s.Customers[ch.CustomerID]
318			if !ok {
319				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
320			}
321			if c.PlanID == "" {
322				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
323			}
324			if !validMonth(ch.Month) {
325				return fmt.Errorf("方案变更 %q 的生效月无效", key)
326			}
327			if _, ok := s.Plans[ch.PlanID]; !ok {
328				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
329			}
330			if strings.TrimSpace(ch.Reason) == "" {
331				return fmt.Errorf("方案变更 %q 的原因为空", key)
332			}
333		}
334		for id, u := range s.Usage {
335			if u == nil {
336				return fmt.Errorf("用量 %q 的数据为空", id)
337			}
338			if u.ID != id {
339				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
340			}
341			if u.ID == "" {
342				return errors.New("存在空的用量标识")
343			}
344			if _, ok := s.Customers[u.CustomerID]; !ok {
345				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
346			}
347			if u.Quantity <= 0 {
348				return fmt.Errorf("用量 %q 的数量非正", u.ID)
349			}
350			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
351				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
352			}
353		}
354		for key, b := range s.Bills {
355			if b == nil {
356				return fmt.Errorf("账单 %q 的数据为空", key)
357			}
358			if billKey(b.CustomerID, b.Month) != key {
359				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
360			}
361			if _, ok := s.Customers[b.CustomerID]; !ok {
362				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
363			}
364			if !validMonth(b.Month) {
365				return fmt.Errorf("账单 %q 的月份无效", key)
366			}
367			if b.MonthlyFee < 0 {
368				return fmt.Errorf("账单 %q 的月费为负", key)
369			}
370			// 仅月费大于 0 的账单允许空用量明细（无用量也须出账收取月费）。
371			if len(b.Lines) == 0 && b.MonthlyFee == 0 {
372				return fmt.Errorf("账单 %q 没有明细", key)
373			}
374			var qty, fee int64
375			for _, ln := range b.Lines {
376				u, ok := s.Usage[ln.UsageID]
377				if !ok {
378					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
379				}
380				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
381					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
382				}
383				if !inMonth(u.Time, b.Month) {
384					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
385				}
386				var err error
387				qty, err = add64(qty, ln.Quantity)
388				if err != nil {
389					return fmt.Errorf("账单 %q 汇总数量溢出", key)
390				}
391				fee, err = add64(fee, ln.LineFee)
392				if err != nil {
393					return fmt.Errorf("账单 %q 汇总金额溢出", key)
394				}
395			}
396			if qty != b.TotalQty {
397				return fmt.Errorf("账单 %q 总数量与明细不符", key)
398			}
399			// 原总金额 = 月费 + 全月用量费；月费不计入逐条用量小计，故明细
400			// 小计之和等于用量费（总金额 − 月费）。月费与总金额均非负，相减
401			// 不会溢出；总金额为负或小于月费时此处必然不符。
402			if usageFee := b.TotalFee - b.MonthlyFee; fee != usageFee {
403				return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费（明细小计合计 %d 分，月费 %d 分，总金额 %d 分）",
404					key, fee, b.MonthlyFee, b.TotalFee)
405			}
406			c := s.Customers[b.CustomerID]
407			switch b.Pricing {
408			case "", "fixed":
409				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
410				// 携带阶梯方案信息、分段或月费。
411				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
412					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
413				}
414				if b.MonthlyFee != 0 {
415					return fmt.Errorf("账单 %q 是固定单价账单但携带月费", key)
416				}
417				for _, ln := range b.Lines {
418					if len(ln.Segments) > 0 {
419						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
420					}
421					lf, err := mul64(ln.Quantity, c.Price)
422					if err != nil {
423						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
424					}
425					if lf != ln.LineFee {
426						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
427					}
428				}
429				if b.UnitPrice != c.Price {
430					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
431				}
432			case "tiered":
433				if err := s.validateTieredBill(key, b, c); err != nil {
434					return err
435				}
436			default:
437				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
438			}
439			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
440			// 而已入账记录理应全部在明细中）。
441			for _, u := range s.Usage {
442				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
443					found := false
444					for _, ln := range b.Lines {
445						if ln.UsageID == u.ID {
446							found = true
447							break
448						}
449					}
450					if !found {
451						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
452					}
453				}
454			}
455		}
