457		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
458		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
459		// 允许同名，各自判重与撤销。
460		if s.NextSeq < 0 {
461			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
462		}
463		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
464		for id, a := range s.Adjustments {
465			if a == nil {
466				return fmt.Errorf("调整 %q 的数据为空", id)
467			}
468			if a.ID != id {
469				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
470			}
471			if a.ID == "" {
472				return errors.New("存在空的调整标识")
473			}
474			if a.Amount == 0 {
475				return fmt.Errorf("调整 %q 的金额为零", id)
476			}
477			if strings.TrimSpace(a.Reason) == "" {
478				return fmt.Errorf("调整 %q 的原因为空", id)
479			}
480			if !validMonth(a.Month) {
481				return fmt.Errorf("调整 %q 的月份无效", id)
482			}
483			if _, ok := s.Customers[a.CustomerID]; !ok {
484				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
485			}
486			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
487				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
488			}
489			if a.Seq < 1 || a.Seq > s.NextSeq {
490				return fmt.Errorf("调整 %q 的操作序号越界", id)
491			}
492			if prev, dup := seenSeq[a.Seq]; dup {
493				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
494			}
495			seenSeq[a.Seq] = "调整 " + id
496			if a.Revoked {
497				if strings.TrimSpace(a.RevokeReason) == "" {
498					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
499				}
500				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
501					return fmt.Errorf("调整 %q 的撤销序号越界", id)
502				}
503				if prev, dup := seenSeq[a.RevokeSeq]; dup {
504					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
505				}
506				seenSeq[a.RevokeSeq] = "撤销调整 " + id
507			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
508				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
509			}
510		}
511		for id, p := range s.Payments {
512			if p == nil {
513				return fmt.Errorf("收款 %q 的数据为空", id)
514			}
515			if p.ID != id {
516				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
517			}
518			if p.ID == "" {
519				return errors.New("存在空的收款标识")
520			}
521			if p.Total <= 0 {
522				return fmt.Errorf("收款 %q 的总额不是正整数", id)
523			}
524			if strings.TrimSpace(p.Note) == "" {
525				return fmt.Errorf("收款 %q 的备注为空", id)
526			}
527			if _, ok := s.Customers[p.CustomerID]; !ok {
528				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
529			}
530			if len(p.Allocations) == 0 {
531				return fmt.Errorf("收款 %q 没有分配", id)
532			}
533			seenMonths := make(map[string]bool)
534			var sum int64
535			for _, al := range p.Allocations {
536				if !validMonth(al.Month) {
537					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
538				}
539				if seenMonths[al.Month] {
540					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
541				}
542				seenMonths[al.Month] = true
543				if al.Amount <= 0 {
544					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
545				}
546				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
547					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
548				}
549				var err error
550				sum, err = add64(sum, al.Amount)
551				if err != nil {
552					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
553				}
554			}
555			if sum != p.Total {
556				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
557			}
558			if p.Seq < 1 || p.Seq > s.NextSeq {
559				return fmt.Errorf("收款 %q 的操作序号越界", id)
560			}
561			if prev, dup := seenSeq[p.Seq]; dup {
562				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
563			}
564			seenSeq[p.Seq] = "收款 " + id
565			if p.Revoked {
566				if strings.TrimSpace(p.RevokeReason) == "" {
567					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
568				}
569				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
570					return fmt.Errorf("收款 %q 的撤销序号越界", id)
571				}
572				if prev, dup := seenSeq[p.RevokeSeq]; dup {
573					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
574				}
575				seenSeq[p.RevokeSeq] = "撤销收款 " + id
576			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
577				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
578			}
579		}
580		// 分配更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
581		// 更正标识与收款、调整标识命名空间相互独立，允许同名。
582		for id, c := range s.Corrections {
583			if c == nil {
584				return fmt.Errorf("更正 %q 的数据为空", id)
585			}
586			if c.ID != id {
587				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
588			}
589			if c.ID == "" {
590				return errors.New("存在空的更正标识")
591			}
592			p, ok := s.Payments[c.PaymentID]
593			if !ok {
594				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
595			}
596			if strings.TrimSpace(c.Reason) == "" {
597				return fmt.Errorf("更正 %q 的原因为空", id)
598			}
599			if len(c.Allocations) == 0 {
600				return fmt.Errorf("更正 %q 没有新分配", id)
601			}
602			seenMonths := make(map[string]bool)
603			var sum int64
604			for _, al := range c.Allocations {
605				if !validMonth(al.Month) {
606					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
607				}
608				if seenMonths[al.Month] {
609					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
610				}
611				seenMonths[al.Month] = true
612				if al.Amount <= 0 {
613					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
614				}
615				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
616					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
617				}
618				var err error
619				sum, err = add64(sum, al.Amount)
620				if err != nil {
621					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
622				}
623			}
624			if sum != p.Total {
625				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
626			}
627			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
628				return fmt.Errorf("更正 %q 的操作序号越界", id)
629			}
630			if p.Revoked && c.Seq > p.RevokeSeq {
631				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
632			}
633			if prev, dup := seenSeq[c.Seq]; dup {
634				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
635			}
636			seenSeq[c.Seq] = "更正 " + id
637		}
638		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
639		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
640		// 计入之和）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明金额与记录不一致。
641		for key, b := range s.Bills {
642			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
643			if err != nil {
644				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
645			}
646			received, err := paymentReceived(s, b.CustomerID, b.Month)
647			if err != nil {
648				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
649			}
650			if received > payable {
651				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
652			}
653		}
654		return nil
655	}
