657	// validatePlanRules 校验阶梯方案的标识、名称、月费与阶梯规则本身自洽：
658	// 月费为非负整数分，至少一档，有限上限为严格递增的正整数，最后一档无
659	// 上限，单价非负。
660	func validatePlanRules(p *plan) error {
661		if p.ID == "" || p.Name == "" {
662			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
663		}
664		if p.MonthlyFee < 0 {
665			return fmt.Errorf("方案 %q 的月费为负", p.ID)
666		}
667		if len(p.Tiers) == 0 {
668			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
669		}
670		prev := int64(0)
671		for i, t := range p.Tiers {
672			if t.Price < 0 {
673				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
674			}
675			if i == len(p.Tiers)-1 {
676				if t.Limit != 0 {
677					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
678				}
679			} else {
680				if t.Limit <= 0 {
681					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
682				}
683				if t.Limit <= prev {
684					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
685				}
686				prev = t.Limit
687			}
688		}
689		return nil
690	}
