692	// tiersEqual 判定两份阶梯规则完全相同。
693	func tiersEqual(a, b []tier) bool {
694		if len(a) != len(b) {
695			return false
696		}
697		for i := range a {
698			if a[i] != b[i] {
699				return false
700			}
701		}
702		return true
703	}
704	
705	// segmentsEqual 判定两份分段列表完全相同。
706	func segmentsEqual(a, b []lineSegment) bool {
707		if len(a) != len(b) {
708			return false
709		}
710		for i := range a {
711			if a[i] != b[i] {
712				return false
713			}
714		}
715		return true
716	}
