718	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
719	// 标识字典序）排列，即阶梯计价的计价顺序。
720	func sortedByInstant(recs []*usageRecord) bool {
721		for i := 1; i < len(recs); i++ {
722			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
723			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
724			ui, uj := ti.UTC(), tj.UTC()
725			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
726				return false
727			}
728		}
729		return true
730	}
