732	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
733	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
734	// 小计、各档合计与总金额；任何不符都视为数据损坏。
735	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
736		if b.PlanID == "" {
737			return fmt.Errorf("账单 %q 缺少方案标识", key)
738		}
739		p, ok := s.Plans[b.PlanID]
740		if !ok {
741			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
742		}
743		if b.PlanName != p.Name {
744			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
745		}
746		if !tiersEqual(b.PlanTiers, p.Tiers) {
747			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
748		}
749		if b.MonthlyFee != p.MonthlyFee {
750			return fmt.Errorf("账单 %q 的月费快照与方案 %q 不符", key, b.PlanID)
751		}
752		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
753		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
754		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
755			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
756		}
757		if b.UnitPrice != 0 {
758			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
759		}
760		if len(b.TierTotals) != len(p.Tiers) {
761			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
762		}
763		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
764		recs := make([]*usageRecord, len(b.Lines))
765		for i, ln := range b.Lines {
766			recs[i] = s.Usage[ln.UsageID]
767		}
768		if !sortedByInstant(recs) {
769			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
770		}
771		priced, err := tieredPrice(p.Tiers, recs)
772		if err != nil {
773			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
774		}
775		for i, ln := range b.Lines {
776			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
777				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
778			}
779			if ln.LineFee != priced.lines[i].fee {
780				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
781			}
782		}
783		for i, tt := range b.TierTotals {
784			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
785				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
786			}
787		}
788		// 原总金额 = 月费 + 全月用量费；月费不进入分档合计与逐条小计。
789		wantTotal, err := add64(priced.totalFee, b.MonthlyFee)
790		if err != nil || wantTotal != b.TotalFee {
791			return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费", key)
792		}
793		return nil
794	}
