796	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
797	// 只有完整保存成功后调用方才会向用户报告成功。
798	func (s *state) save() error {
799		if err := s.validate(); err != nil {
800			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
801		}
802		data, err := json.MarshalIndent(s, "", "  ")
803		if err != nil {
804			return fmt.Errorf("序列化数据失败: %w", err)
805		}
806		data = append(data, '\n')
807	
808		tmp := s.path + ".tmp"
809		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
810		if err != nil {
811			return fmt.Errorf("写入临时数据文件失败: %w", err)
812		}
813		if _, err := f.Write(data); err != nil {
814			f.Close()
815			os.Remove(tmp)
816			return fmt.Errorf("写入临时数据文件失败: %w", err)
817		}
818		if err := f.Sync(); err != nil {
819			f.Close()
820			os.Remove(tmp)
821			return fmt.Errorf("同步数据文件失败: %w", err)
822		}
823		if err := f.Close(); err != nil {
824			os.Remove(tmp)
825			return fmt.Errorf("关闭数据文件失败: %w", err)
826		}
827		if err := os.Rename(tmp, s.path); err != nil {
828			os.Remove(tmp)
829			return fmt.Errorf("替换数据文件失败: %w", err)
830		}
831		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
832			dir.Sync()
833			dir.Close()
834		}
835		return nil
836	}
837	
838	func billKey(customerID, month string) string {
839		return customerID + "|" + month
840	}
841	
842	func planChangeKey(customerID, month string) string {
843		return customerID + "|" + month
844	}
845	
846	// planChangesFor 返回某客户的全部方案变更，按生效月升序。
847	func (s *state) planChangesFor(customerID string) []*planChange {
848		var list []*planChange
849		for _, ch := range s.PlanChanges {
850			if ch.CustomerID == customerID {
851				list = append(list, ch)
852			}
853		}
854		sort.Slice(list, func(i, j int) bool { return list[i].Month < list[j].Month })
855		return list
856	}
857	
858	// effectivePlanID 返回客户在某 UTC 自然月实际适用的阶梯方案标识：
859	// 创建时绑定的初始方案，被生效月不晚于该月的最后一次变更替换。
860	func (s *state) effectivePlanID(cust *customer, month string) string {
861		planID := cust.PlanID
862		latest := ""
863		for _, ch := range s.PlanChanges {
864			if ch.CustomerID == cust.ID && ch.Month <= month && ch.Month >= latest {
865				latest = ch.Month
866				planID = ch.PlanID
867			}
868		}
869		return planID
870	}
871	
872	// sealed 报告某客户的指定月份是否已封账。
873	func (s *state) sealed(customerID, month string) bool {
874		_, ok := s.Bills[billKey(customerID, month)]
875		return ok
876	}
877	
878	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
879	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
880		var list []*adjustment
881		for _, a := range s.Adjustments {
882			if a.CustomerID == customerID && a.Month == month {
883				list = append(list, a)
884			}
885		}
886		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
887		return list
888	}
889	
890	// correctionsFor 返回某收款的全部分配更正，按操作序号升序。
891	func correctionsFor(s *state, paymentID string) []*correction {
892		var list []*correction
893		for _, c := range s.Corrections {
894			if c.PaymentID == paymentID {
895				list = append(list, c)
896			}
897		}
898		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
899		return list
900	}
901	
902	// currentAllocations 返回一笔收款当前生效的分配：无更正时为首次登记的
903	// 原始分配，否则为序号最大（最新）的更正的分配。
904	func currentAllocations(s *state, p *payment) []paymentAllocation {
905		var latest *correction
906		for _, c := range s.Corrections {
907			if c.PaymentID == p.ID && (latest == nil || c.Seq > latest.Seq) {
908				latest = c
909			}
910		}
911		if latest != nil {
912			return latest.Allocations
913		}
914		return p.Allocations
915	}
916	
917	// allocAmountFor 返回分配列表中指定月份的金额；无该月分配时为 0。
918	func allocAmountFor(allocs []paymentAllocation, month string) int64 {
919		for _, al := range allocs {
920			if al.Month == month {
921				return al.Amount
922			}
923		}
924		return 0
925	}
926	
927	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
928	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
929	func paymentsEverFor(s *state, customerID, month string) []*payment {
930		var list []*payment
931		for _, p := range s.Payments {
932			if p.CustomerID != customerID {
933				continue
934			}
935			involved := p.amountFor(month) > 0
936			if !involved {
937				for _, c := range s.Corrections {
938					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
939						involved = true
940						break
941					}
942				}
943			}
944			if involved {
945				list = append(list, p)
946			}
947		}
948		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
949		return list
950	}
951	
952	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入的实收之和。
953	// 各笔分配均为正整数，用非负 64 位加法累加，溢出时返回错误。
954	func paymentReceived(s *state, customerID, month string) (int64, error) {
955		var received int64
956		for _, p := range s.Payments {
957			if p.CustomerID != customerID || p.Revoked {
958				continue
959			}
960			amt := allocAmountFor(currentAllocations(s, p), month)
961			if amt <= 0 {
962				continue
963			}
964			var err error
965			received, err = add64(received, amt)
966			if err != nil {
967				return 0, err
968			}
969		}
970		return received, nil
971	}
972	
973	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
974	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
975	
976	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
977	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
978	// [0, 有符号 64 位最大值] 内，全程整数运算。
979	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
980		var amounts []int64
981		for _, a := range adjs {
982			if !a.Revoked {
983				amounts = append(amounts, a.Amount)
984			}
985		}
986		net, err = sumSigned64(amounts...)
987		if err != nil {
988			return 0, 0, err
989		}
990		payable, err = addSigned64(b.TotalFee, net)
991		if err != nil {
992			return 0, 0, err
993		}
994		if payable < 0 {
995			return 0, 0, errPayableOutOfRange
996		}
997		return net, payable, nil
998	}
999

