226	func cmdUsageImport(dir, file string) error {
227		var reader io.ReadCloser
228		var source string
229		if file == "-" {
230			reader = io.NopCloser(os.Stdin)
231			source = "标准输入"
232		} else {
233			f, err := os.Open(file)
234			if err != nil {
235				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
236			}
237			reader = f
238			source = file
239		}
240		defer reader.Close()
241	
242		rows, parseErrs := parseUsageFile(reader)
243	
244		s, err := loadStore(dir)
245		if err != nil {
246			return err
247		}
248	
249		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
250		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
251		var problems []string
252		problems = append(problems, parseErrs...)
253	
254		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
255		var ordered []*parsedRow
256		newCount, dupCount := 0, 0
257	
258		for _, r := range rows {
259			cust, ok := s.Customers[r.rec.CustomerID]
260			if !ok {
261				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
262				continue
263			}
264			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
265			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
266			// 溢出（金额单位：分）。
267			if cust.PlanID == "" {
268				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
269					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
270					continue
271				}
272			} else {
273				rec := r.rec
274				month := r.t.UTC().Format("2006-01")
275				planID := s.effectivePlanID(cust, month)
276				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
277					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, month, planID, err))
278					continue
279				}
280			}
281	
282			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
283			var existing *usageRecord
284			if inStore, ok := s.Usage[r.rec.ID]; ok {
285				existing = inStore
286			} else if inBatch, ok := accepted[r.rec.ID]; ok {
287				existing = &inBatch.rec
288			}
289	
290			if existing != nil {
291				if !sameUsage(existing, &r.rec, r.t) {
292					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
293						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
294					continue
295				}
296				dupCount++
297				continue
298			}
299	
300			// 全新标识：不得进入该客户已封账的 UTC 自然月。
301			month := r.t.UTC().Format("2006-01")
302			if s.sealed(r.rec.CustomerID, month) {
303				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
304					r.line, r.rec.CustomerID, month, r.rec.ID))
305				continue
306			}
307	
308			rr := r
309			accepted[r.rec.ID] = rr
310			ordered = append(ordered, rr)
311			newCount++
312		}
313	
314		if len(problems) > 0 {
315			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
316		}
317	
318		for _, r := range ordered {
319			rec := r.rec
320			s.Usage[rec.ID] = &rec
321		}
322		if err := s.save(); err != nil {
323			return err
324		}
325		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
326		return nil
327	}
