329	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
330	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
331		cr := csv.NewReader(r)
332		cr.FieldsPerRecord = 4
333		cr.TrimLeadingSpace = true
334	
335		header, err := cr.Read()
336		if err == io.EOF {
337			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
338		}
339		if err != nil {
340			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
341		}
342		for i := range header {
343			header[i] = strings.TrimSpace(header[i])
344		}
345		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
346			header[2] != "time" || header[3] != "quantity" {
347			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
348		}
349	
350		var rows []*parsedRow
351		var problems []string
352		line := 1
353		for {
354			rec, err := cr.Read()
355			if err == io.EOF {
356				break
357			}
358			line++
359			if err != nil {
360				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
361				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
362					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
363					break
364				}
365				continue
366			}
367			for i := range rec {
368				rec[i] = strings.TrimSpace(rec[i])
369			}
370	
371			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
372			if id == "" {
373				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
374				continue
375			}
376			if custID == "" {
377				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
378				continue
379			}
380			t, err := time.Parse(time.RFC3339, ts)
381			if err != nil {
382				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
383				continue
384			}
385			qty, err := strconv.ParseInt(qtyText, 10, 64)
386			if err != nil {
387				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
388				continue
389			}
390			if qty <= 0 {
391				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
392				continue
393			}
394	
395			rows = append(rows, &parsedRow{
396				line: line,
397				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
398				t:    t,
399			})
400		}
401		return rows, problems
402	}
