404	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
405	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
406	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
407		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
408			return false
409		}
410		et, err := time.Parse(time.RFC3339, existing.Time)
411		if err != nil {
412			return existing.Time == candidate.Time
413		}
414		return et.Equal(candidateT)
415	}
416	
417	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
418	func validMonth(m string) bool {
419		t, err := time.Parse("2006-01", m)
420		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
421			return false
422		}
423		return true
424	}
425	
426	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
427	func inMonth(rfc3339, month string) bool {
428		t, err := time.Parse(time.RFC3339, rfc3339)
429		if err != nil {
430			return false
431		}
432		return t.UTC().Format("2006-01") == month
433	}
434	
435	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
436	// 入参时间均已在载入/导入时校验为 RFC3339。
437	func utcMonth(rfc3339 string) string {
438		t, _ := time.Parse(time.RFC3339, rfc3339)
439		return t.UTC().Format("2006-01")
440	}
