442	func cmdBillSettle(dir, customerID, month string) error {
443		if !validMonth(month) {
444			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
445		}
446		s, err := loadStore(dir)
447		if err != nil {
448			return err
449		}
450		cust, ok := s.Customers[customerID]
451		if !ok {
452			return fmt.Errorf("客户标识 %q 不存在", customerID)
453		}
454	
455		key := billKey(customerID, month)
456		if existing, ok := s.Bills[key]; ok {
457			// 幂等：同一客户同一月份重复结算，直接返回原账单，
458			// 不重新计费、不产生新账单或调整、不落盘。
459			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
460			printBill(existing, cust, s)
461			return nil
462		}
463	
464		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
465		// 有效方案月费大于 0 的阶梯客户即使无用量也须出账（收取一次整月月费）；
466		// 月费为 0 的方案与固定单价客户无用量时仍拒绝结算且不封账。
467		inMonthRecs := monthUsage(s, customerID, month)
468		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
469			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
470		}
471	
472		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
473		if cust.PlanID != "" {
474			return settleTiered(s, cust, month, inMonthRecs)
475		}
476	
477		b, err := buildFixedBill(cust, month, inMonthRecs)
478		if err != nil {
479			return fmt.Errorf("%v，拒绝结算且不封账", err)
480		}
481		s.Bills[key] = b
482	
483		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
484		if err := s.save(); err != nil {
485			delete(s.Bills, key)
486			return err
487		}
488		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
489		printBill(b, cust, s)
490		return nil
491	}
