513	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
514	// 用量，并按计价顺序（解析后的时间点升序、同一时间按标识字典序）排列。
515	func monthUsage(s *state, customerID, month string) []*usageRecord {
516		var recs []*usageRecord
517		for _, u := range s.Usage {
518			if u.CustomerID == customerID && inMonth(u.Time, month) {
519				recs = append(recs, u)
520			}
521		}
522		sortByInstant(recs)
523		return recs
524	}
