526	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
527	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
528	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
529		lines := make([]billLine, 0, len(recs))
530		var totalQty, totalFee int64
531		for _, u := range recs {
532			lineFee, err := mul64(u.Quantity, cust.Price)
533			if err != nil {
534				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
535			}
536			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
537				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
538			}
539			if totalFee, err = add64(totalFee, lineFee); err != nil {
540				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
541			}
542			lines = append(lines, billLine{
543				UsageID:  u.ID,
544				Time:     u.Time,
545				Quantity: u.Quantity,
546				LineFee:  lineFee,
547			})
548		}
549		return &bill{
550			ID:         stableBillID(cust.ID, month),
551			CustomerID: cust.ID,
552			Month:      month,
553			TotalQty:   totalQty,
554			UnitPrice:  cust.Price,
555			TotalFee:   totalFee,
556			Lines:      lines,
557			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
558		}, nil
559	}
560	
561	func sortByInstant(us []*usageRecord) {
562		// 入参时间均已在载入/导入时校验为 RFC3339。
563		sort.Slice(us, func(i, j int) bool {
564			ti, _ := time.Parse(time.RFC3339, us[i].Time)
565			tj, _ := time.Parse(time.RFC3339, us[j].Time)
566			ui, uj := ti.UTC(), tj.UTC()
567			if !ui.Equal(uj) {
568				return ui.Before(uj)
569			}
570			return us[i].ID < us[j].ID
571		})
572	}
