580	func printBill(b *bill, cust *customer, s *state) {
581		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
582		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
583		// 涉及该月即纳入，即使后来被更正移出。
584		pays := paymentsEverFor(s, b.CustomerID, b.Month)
585		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
586		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
587		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
588		tiered := b.Pricing == "tiered"
589		if tiered {
590			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
591			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
592			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
593			fmt.Fprintln(stdout, "阶梯规则：")
594			for i, t := range b.PlanTiers {
595				if t.Limit == 0 {
596					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
597				} else {
598					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
599				}
600			}
601		} else {
602			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
603		}
604		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
605		if tiered {
606			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
607			// 月费不计入总数量、各档金额或逐条小计。
608			usageFee := b.TotalFee - b.MonthlyFee
609			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
610			fmt.Fprintf(stdout, "用量费：%d 分（%s）\n", usageFee, moneyFen(usageFee))
611			fmt.Fprintf(stdout, "原总金额：%d 分（%s，月费加全月用量费）\n", b.TotalFee, moneyFen(b.TotalFee))
612		} else {
613			fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
614		}
615		if tiered {
616			fmt.Fprintln(stdout, "各档合计：")
617			for i, tt := range b.TierTotals {
618				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
619					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
620			}
621		}
622		// 数据在载入时已校验一致，此处计算不会出错。
623		net, payable, _ := billTotals(b, adjs)
624		received, _ := paymentReceived(s, b.CustomerID, b.Month)
625		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
626		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
627		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
628		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
629		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
630		if len(b.Lines) == 0 {
631			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
632		} else {
633			fmt.Fprintln(stdout, "明细：")
634		}
635		for i, ln := range b.Lines {
636			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
637				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
638			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
639			for j, seg := range ln.Segments {
640				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
641					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
642			}
643		}
644		if len(adjs) == 0 {
645			fmt.Fprintln(stdout, "调整与撤销历史：无")
646		} else {
647			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
648			for i, ev := range historyEvents(adjs) {
649				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
650			}
651		}
652		if len(pays) == 0 {
653			fmt.Fprintln(stdout, "收款与撤销历史：无")
654		} else {
655			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
656			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
657				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
658			}
659		}
660	}
