662	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
663	func historyEvents(adjs []*adjustment) []string {
664		type event struct {
665			seq  int64
666			text string
667		}
668		var events []event
669		for _, a := range adjs {
670			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
671				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
672			if a.Revoked {
673				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
674					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
675			}
676		}
677		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
678		out := make([]string, len(events))
679		for i, ev := range events {
680			out[i] = ev.text
681		}
682		return out
683	}
684	
685	func adjustKind(amount int64) string {
686		if amount > 0 {
687			return "补收"
688		}
689		return "减免"
690	}
691	
692	func adjustStatus(a *adjustment) string {
693		if a.Revoked {
694			return "已撤销"
695		}
696		return "生效中"
697	}
698	
699	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
700	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
701	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
702	// 的最新分配。
703	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
704		type event struct {
705			seq  int64
706			text string
707		}
708		var events []event
709		for _, p := range pays {
710			alloc := p.amountFor(month)
711			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
712				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
713			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
714			running := alloc
715			for _, c := range correctionsFor(s, p.ID) {
716				after := allocAmountFor(c.Allocations, month)
717				if running == 0 && after == 0 {
718					continue // 本次更正不涉及本账单
719				}
720				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
721					c.ID, c.Reason, p.ID, running, after)})
722				running = after
723			}
724			if p.Revoked {
725				// 整笔撤销取消的是撤销时的最新分配。
726				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
727					p.ID, p.RevokeReason, p.ID, p.Total, running)})
728			}
729		}
730		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
731		out := make([]string, len(events))
732		for i, ev := range events {
733			out[i] = ev.text
734		}
735		return out
736	}
737	
738	func paymentStatus(p *payment) string {
739		if p.Revoked {
740			return "已撤销"
741		}
742		return "实收中"
743	}
