758	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
759		if !validMonth(month) {
760			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
761		}
762		if strings.TrimSpace(adjID) == "" {
763			return fmt.Errorf("调整标识不能为空")
764		}
765		amount, err := parseAmount(amountText)
766		if err != nil {
767			return err
768		}
769		if strings.TrimSpace(reason) == "" {
770			return fmt.Errorf("调整原因不能为空")
771		}
772	
773		s, err := loadStore(dir)
774		if err != nil {
775			return err
776		}
777		if _, ok := s.Customers[customerID]; !ok {
778			return fmt.Errorf("客户标识 %q 不存在", customerID)
779		}
780		b, ok := s.Bills[billKey(customerID, month)]
781		if !ok {
782			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
783		}
784	
785		if existing, ok := s.Adjustments[adjID]; ok {
786			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
787			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
788			if existing.CustomerID == customerID && existing.Month == month &&
789				existing.Amount == amount && existing.Reason == reason {
790				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
791				printAdjustment(existing, s)
792				return nil
793			}
794			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
795				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
796		}
797	
798		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
799		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
800		// 不占用该调整标识。
801		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
802		if err != nil {
803			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
804		}
805		received, err := paymentReceived(s, customerID, month)
806		if err != nil {
807			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
808		}
809		newPayable, err := addSigned64(payable, amount)
810		if err != nil {
811			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
812		}
813		if newPayable < 0 {
814			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
815		}
816		if newPayable < received {
817			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
818				newPayable, received, payable, amount)
819		}
820	
821		a := &adjustment{
822			ID:         adjID,
823			CustomerID: customerID,
824			Month:      month,
825			Amount:     amount,
826			Reason:     reason,
827			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
828		}
829		s.NextSeq++
830		a.Seq = s.NextSeq
831		s.Adjustments[adjID] = a
832	
833		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
834		// 该调整标识不被占用。
835		if err := s.save(); err != nil {
836			delete(s.Adjustments, adjID)
837			s.NextSeq--
838			return err
839		}
840		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
841			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
842		printAdjustment(a, s)
843		return nil
844	}
