846	func cmdBillRevoke(dir, adjID, reason string) error {
847		if strings.TrimSpace(adjID) == "" {
848			return fmt.Errorf("调整标识不能为空")
849		}
850		if strings.TrimSpace(reason) == "" {
851			return fmt.Errorf("撤销原因不能为空")
852		}
853	
854		s, err := loadStore(dir)
855		if err != nil {
856			return err
857		}
858		a, ok := s.Adjustments[adjID]
859		if !ok {
860			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
861		}
862	
863		if a.Revoked {
864			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
865			// 改用其他原因则拒绝。
866			if a.RevokeReason == reason {
867				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
868				printAdjustment(a, s)
869				return nil
870			}
871			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
872		}
873	
874		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
875		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
876		// 改变余额后重试。
877		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
878		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
879		if err != nil {
880			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
881		}
882		received, err := paymentReceived(s, a.CustomerID, a.Month)
883		if err != nil {
884			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
885		}
886		neg, err := neg64(a.Amount)
887		if err != nil {
888			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
889		}
890		newPayable, err := addSigned64(payable, neg)
891		if err != nil {
892			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
893				payable, a.Amount)
894		}
895		if newPayable < 0 {
896			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
897				newPayable, payable, a.Amount)
898		}
899		if newPayable < received {
900			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
901				newPayable, received, payable, a.Amount)
902		}
903	
904		a.Revoked = true
905		a.RevokeReason = reason
906		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
907		s.NextSeq++
908		a.RevokeSeq = s.NextSeq
909	
910		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
911		if err := s.save(); err != nil {
912			a.Revoked = false
913			a.RevokeReason = ""
914			a.RevokedAt = ""
915			a.RevokeSeq = 0
916			s.NextSeq--
917			return err
918		}
919		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
920			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
921		printAdjustment(a, s)
922		return nil
923	}
