968	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
969		total, err := parsePositiveAmount(totalText)
970		if err != nil {
971			return err
972		}
973		allocs, err := parseAllocations(allocArgs)
974		if err != nil {
975			return err
976		}
977		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
978		var sum int64
979		for _, al := range allocs {
980			sum, err = add64(sum, al.Amount)
981			if err != nil {
982				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
983			}
984		}
985		if sum != total {
986			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
987		}
988		return registerPayment(dir, customerID, payID, total, note, allocs)
989	}
