991	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
992	// 月份不得重复，每项金额为正整数分。
993	func parseAllocations(args []string) ([]paymentAllocation, error) {
994		if len(args) == 0 {
995			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
996		}
997		seen := make(map[string]bool)
998		allocs := make([]paymentAllocation, 0, len(args))
999		for _, arg := range args {
1000			parts := strings.Split(arg, ":")
1001			if len(parts) != 2 {
1002				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1003			}
1004			month := strings.TrimSpace(parts[0])
1005			if !validMonth(month) {
1006				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1007			}
1008			if seen[month] {
1009				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1010			}
1011			seen[month] = true
1012			amount, err := parsePositiveAmount(parts[1])
1013			if err != nil {
1014				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1015			}
1016			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1017		}
1018		return allocs, nil
1019	}
