1021	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1022	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1023	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1024		if strings.TrimSpace(payID) == "" {
1025			return fmt.Errorf("收款标识不能为空")
1026		}
1027		if strings.TrimSpace(note) == "" {
1028			return fmt.Errorf("收款备注不能为空")
1029		}
1030		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1031		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1032	
1033		s, err := loadStore(dir)
1034		if err != nil {
1035			return err
1036		}
1037		if _, ok := s.Customers[customerID]; !ok {
1038			return fmt.Errorf("客户标识 %q 不存在", customerID)
1039		}
1040		for _, al := range allocs {
1041			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1042				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1043			}
1044		}
1045	
1046		if existing, ok := s.Payments[payID]; ok {
1047			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1048			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1049			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1050			if samePaymentContent(existing, customerID, total, note, allocs) {
1051				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1052				printPayment(existing, s)
1053				return nil
1054			}
1055			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1056				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1057		}
1058	
1059		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1060		for _, al := range allocs {
1061			b := s.Bills[billKey(customerID, al.Month)]
1062			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1063			if err != nil {
1064				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1065			}
1066			received, err := paymentReceived(s, customerID, al.Month)
1067			if err != nil {
1068				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1069			}
1070			if payable == 0 {
1071				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1072			}
1073			if al.Amount > payable-received {
1074				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1075					al.Amount, payable-received, customerID, al.Month, payable, received)
1076			}
1077		}
1078	
1079		p := &payment{
1080			ID:          payID,
1081			CustomerID:  customerID,
1082			Total:       total,
1083			Note:        note,
1084			Allocations: allocs,
1085			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1086		}
1087		s.NextSeq++
1088		p.Seq = s.NextSeq
1089		s.Payments[payID] = p
1090	
1091		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1092		// 一切不生效，该收款标识不被占用。
1093		if err := s.save(); err != nil {
1094			delete(s.Payments, payID)
1095			s.NextSeq--
1096			return err
1097		}
1098		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1099		printAllocationBalances(s, p, allocs)
1100		fmt.Fprintln(stdout)
1101		printPayment(p, s)
1102		return nil
1103	}
