1105	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1106	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1107	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1108		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1109			return false
1110		}
1111		return sameAllocations(p.Allocations, allocs)
1112	}
1113	
1114	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1115	func sameAllocations(a, b []paymentAllocation) bool {
1116		if len(a) != len(b) {
1117			return false
1118		}
1119		for _, al := range b {
1120			if allocAmountFor(a, al.Month) != al.Amount {
1121				return false
1122			}
1123		}
1124		return true
1125	}
1126	
1127	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1128	func formatAllocations(allocs []paymentAllocation) string {
1129		parts := make([]string, len(allocs))
1130		for i, al := range allocs {
1131			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1132		}
1133		return strings.Join(parts, ",")
1134	}
