1147	func cmdBillUnpay(dir, payID, reason string) error {
1148		if strings.TrimSpace(payID) == "" {
1149			return fmt.Errorf("收款标识不能为空")
1150		}
1151		if strings.TrimSpace(reason) == "" {
1152			return fmt.Errorf("撤销原因不能为空")
1153		}
1154	
1155		s, err := loadStore(dir)
1156		if err != nil {
1157			return err
1158		}
1159		p, ok := s.Payments[payID]
1160		if !ok {
1161			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1162		}
1163	
1164		if p.Revoked {
1165			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1166			// 改用其他原因则拒绝。
1167			if p.RevokeReason == reason {
1168				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1169				printPayment(p, s)
1170				return nil
1171			}
1172			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1173		}
1174	
1175		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1176		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1177		// 分配、更正与撤销原因永久保留。
1178		p.Revoked = true
1179		p.RevokeReason = reason
1180		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1181		s.NextSeq++
1182		p.RevokeSeq = s.NextSeq
1183	
1184		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1185		if err := s.save(); err != nil {
1186			p.Revoked = false
1187			p.RevokeReason = ""
1188			p.RevokedAt = ""
1189			p.RevokeSeq = 0
1190			s.NextSeq--
1191			return err
1192		}
1193		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1194		printAllocationBalances(s, p, currentAllocations(s, p))
1195		fmt.Fprintln(stdout)
1196		printPayment(p, s)
1197		return nil
1198	}
1199	
1200	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1201	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1202	// 各月应付/实收取自当前库状态。
1203	func printPayment(p *payment, s *state) {
1204		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1205		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1206		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1207		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1208		if p.Revoked {
1209			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1210		} else {
1211			fmt.Fprintf(stdout, "当前状态：实收中\n")
1212		}
1213		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1214		for i, al := range p.Allocations {
1215			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1216			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1217			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1218			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1219				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1220		}
1221		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1222			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1223				len(corrs), formatAllocations(currentAllocations(s, p)))
1224		}
1225	}
