1227	// --- 收款分配更正 ---
1228	
1229	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1230		if strings.TrimSpace(payID) == "" {
1231			return fmt.Errorf("收款标识不能为空")
1232		}
1233		if strings.TrimSpace(corrID) == "" {
1234			return fmt.Errorf("更正标识不能为空")
1235		}
1236		if strings.TrimSpace(reason) == "" {
1237			return fmt.Errorf("更正原因不能为空")
1238		}
1239		allocs, err := parseAllocations(allocArgs)
1240		if err != nil {
1241			return err
1242		}
1243		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1244		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1245	
1246		s, err := loadStore(dir)
1247		if err != nil {
1248			return err
1249		}
1250		p, ok := s.Payments[payID]
1251		if !ok {
1252			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1253		}
1254	
1255		if existing, ok := s.Corrections[corrID]; ok {
1256			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1257			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1258			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1259			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1260				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1261				printCorrection(existing, s)
1262				return nil
1263			}
1264			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1265				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1266		}
1267	
1268		// 新增更正只允许未撤销收款。
1269		if p.Revoked {
1270			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1271		}
1272	
1273		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1274		var sum int64
1275		for _, al := range allocs {
1276			sum, err = add64(sum, al.Amount)
1277			if err != nil {
1278				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1279			}
1280		}
1281		if sum != p.Total {
1282			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1283		}
1284		// 新分配月份须是原客户的已结算账单。
1285		for _, al := range allocs {
1286			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1287				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1288			}
1289		}
1290	
1291		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1292		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1293		current := currentAllocations(s, p)
1294		for _, m := range unionMonths(current, allocs) {
1295			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1296			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1297			if err != nil {
1298				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1299			}
1300			received, err := paymentReceived(s, p.CustomerID, m)
1301			if err != nil {
1302				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1303			}
1304			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1305			received -= allocAmountFor(current, m)
1306			received, err = add64(received, allocAmountFor(allocs, m))
1307			if err != nil {
1308				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1309			}
1310			if received > payable {
1311				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1312					p.CustomerID, m, received, payable)
1313			}
1314		}
1315	
1316		c := &correction{
1317			ID:          corrID,
1318			PaymentID:   payID,
1319			Reason:      reason,
1320			Allocations: allocs,
1321			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1322		}
1323		s.NextSeq++
1324		c.Seq = s.NextSeq
1325		s.Corrections[corrID] = c
1326	
1327		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1328		// 一切不生效，该更正标识不被占用。
1329		if err := s.save(); err != nil {
1330			delete(s.Corrections, corrID)
1331			s.NextSeq--
1332			return err
1333		}
1334		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1335		printCorrection(c, s)
1336		return nil
1337	}
1338	
1339	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1340	func unionMonths(a, b []paymentAllocation) []string {
1341		set := make(map[string]bool, len(a)+len(b))
1342		for _, al := range a {
1343			set[al.Month] = true
1344		}
1345		for _, al := range b {
1346			set[al.Month] = true
1347		}
1348		months := make([]string, 0, len(set))
1349		for m := range set {
1350			months = append(months, m)
1351		}
1352		sort.Strings(months)
1353		return months
1354	}
1355	
1356	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1357	// 新分配，或（首次更正时）收款的原始分配。
1358	func allocationBefore(s *state, c *correction) []paymentAllocation {
1359		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1360		var latest *correction
1361		for _, o := range s.Corrections {
1362			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1363				latest = o
1364			}
1365		}
1366		if latest != nil {
1367			before = latest.Allocations
1368		}
1369		return before
1370	}
