1372	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1373	// 以及前后分配涉及月份的当前余额。
1374	func printCorrection(c *correction, s *state) {
1375		p := s.Payments[c.PaymentID] // 载入时已校验存在
1376		before := allocationBefore(s, c)
1377		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1378		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1379			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1380		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1381		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1382		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1383		fmt.Fprintln(stdout, "涉及月份当前余额：")
1384		for _, m := range unionMonths(before, c.Allocations) {
1385			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1386			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1387			received, _ := paymentReceived(s, p.CustomerID, m)
1388			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1389				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1390				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1391		}
1392	}
