1394	// --- 账后对账流水 ---
1395	
1396	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1397	// 分配更正或撤销收款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1398	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1399	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值。
1400	type ledgerEvent struct {
1401		seq           int64  // 全局操作序号（调整/收款/更正及其撤销共用）
1402		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款
1403		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1404		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1405		deltaReceived int64  // 对实收的影响（分，带符号）
1406		note          string // 原因（调整/更正类）或备注（收款类）
1407		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1408		payTotal      int64  // 收款类事件：汇款总额
1409		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配）
1410		payID         string // 更正事件：关联收款标识
1411		beforeAlloc   int64  // 更正事件：本账单更正前分配
1412		afterAlloc    int64  // 更正事件：本账单更正后分配
1413		afterPayable  int64  // 事件后的应付（回放时填充）
1414		afterReceived int64  // 事件后的实收（回放时填充）
1415	}
1416	
1417	// billLedger 把目标账单的调整、调整撤销、收款、分配更正与收款撤销合并为
1418	// 一条按操作序号升序的流水，并以原总金额为初始应付、零实收为起点逐步回放，
1419	// 填充每个事件之后的三项余额。回放覆盖完整流水（不受查询截止序号限制）：
1420	// 序号重复、撤销先于原操作，或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号
1421	// 64 位最大值，都视为数据异常并拒绝——只检查最终余额会放过中间越界的存档。
1422	// 只读：不修改库、不占用序号、不新增记录。
1423	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1424		var events []ledgerEvent
1425		for _, a := range s.Adjustments {
1426			if a.CustomerID != b.CustomerID || a.Month != b.Month {
1427				continue
1428			}
1429			events = append(events, ledgerEvent{
1430				seq: a.Seq, kind: "调整", refID: a.ID,
1431				deltaPayable: a.Amount, note: a.Reason,
1432			})
1433			if a.Revoked {
1434				neg, err := neg64(a.Amount)
1435				if err != nil {
1436					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出流水", a.ID, a.Amount)
1437				}
1438				events = append(events, ledgerEvent{
1439					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
1440					deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
1441				})
1442			}
1443		}
1444		for _, p := range s.Payments {
1445			if p.CustomerID != b.CustomerID {
1446				continue
1447			}
1448			// 多月汇款只以本账单分配改变实收；更正在其发生序号把本账单分配
1449			// 由前值替换为后值；整笔撤销在同一序号取消撤销时的最新分配。
1450			// 首次登记或任一次更正涉及本账单的，该收款的后续事件都纳入流水。
1451			alloc := p.amountFor(b.Month)
1452			corrs := correctionsFor(s, p.ID)
1453			involved := alloc > 0
1454			if !involved {
1455				for _, c := range corrs {
1456					if allocAmountFor(c.Allocations, b.Month) > 0 {
1457						involved = true
1458						break
1459					}
1460				}
1461			}
1462			if !involved {
1463				continue
1464			}
1465			if alloc > 0 {
1466				events = append(events, ledgerEvent{
1467					seq: p.Seq, kind: "收款", refID: p.ID,
1468					deltaReceived: alloc, note: p.Note,
1469					payTotal: p.Total, payAlloc: alloc,
1470				})
1471			}
1472			running := alloc
1473			for _, c := range corrs {
1474				after := allocAmountFor(c.Allocations, b.Month)
1475				if running == 0 && after == 0 {
1476					continue // 本次更正不涉及本账单
1477				}
1478				events = append(events, ledgerEvent{
1479					seq: c.Seq, kind: "更正", refID: c.ID,
1480					deltaReceived: after - running, note: c.Reason,
1481					payID: p.ID, beforeAlloc: running, afterAlloc: after,
1482				})
1483				running = after
1484			}
1485			if p.Revoked {
1486				events = append(events, ledgerEvent{
1487					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
1488					deltaReceived: -running, note: p.RevokeReason, linkSeq: p.Seq,
1489					payTotal: p.Total, payAlloc: running,
1490				})
1491			}
1492		}
1493		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1494	
1495		// 逐步回放并核验：只把每个事件的金额影响加到运行余额上，不对发生额
1496		// 做累计求和，因此累计补收/收款发生额超过 64 位上限但每步余额合法时
1497		// 仍能成功。
1498		payable := b.TotalFee
1499		var received int64
1500		seen := make(map[int64]string, len(events))
1501		for i := range events {
1502			ev := &events[i]
1503			desc := ev.kind + " " + ev.refID
1504			if prev, dup := seen[ev.seq]; dup {
1505				return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出流水", ev.seq, prev, desc)
1506			}
1507			seen[ev.seq] = desc
1508			if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
1509				return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出流水", desc, ev.seq, ev.linkSeq)
1510			}
1511			var err error
1512			if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
1513				return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1514			}
1515			if received, err = addSigned64(received, ev.deltaReceived); err != nil {
1516				return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1517			}
1518			if payable < 0 {
1519				return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, payable)
1520			}
1521			if received < 0 {
1522				return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, received)
1523			}
1524			if received > payable {
1525				return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出流水", ev.seq, desc, received, payable)
1526			}
1527			ev.afterPayable = payable
1528			ev.afterReceived = received
1529		}
1530		return events, nil
1531	}
1532	
1533	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1534		if !validMonth(month) {
1535			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1536		}
1537		s, err := loadStore(dir)
1538		if err != nil {
1539			return err
1540		}
1541		cust, ok := s.Customers[customerID]
1542		if !ok {
1543			return fmt.Errorf("客户标识 %q 不存在", customerID)
1544		}
1545		b, ok := s.Bills[billKey(customerID, month)]
1546		if !ok {
1547			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1548		}
1549	
1550		// 截止序号使用调整/收款及其撤销共用的已保存全局序号：省略表示最新，
1551		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1552		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1553		cutoff := s.NextSeq
1554		cutoffDesc := "省略，按最新"
1555		if hasCutoff {
1556			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1557			if perr != nil {
1558				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1559			}
1560			if v < 0 {
1561				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1562			}
1563			if v > s.NextSeq {
1564				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1565			}
1566			cutoff = v
1567			cutoffDesc = "指定"
1568		}
1569	
1570		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1571		// 拒绝，不输出部分正常的报告。
1572		events, err := billLedger(s, b)
1573		if err != nil {
1574			return err
1575		}
1576		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1577		return nil
1578	}
1579	
1580	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1581		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1582		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1583		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1584		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1585		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1586		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1587		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1588			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1589	
1590		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1591		payable, received := b.TotalFee, int64(0)
1592		var shown []ledgerEvent
1593		for _, ev := range events {
1594			if ev.seq > cutoff {
1595				continue
1596			}
1597			shown = append(shown, ev)
1598			payable, received = ev.afterPayable, ev.afterReceived
1599		}
1600		if len(shown) == 0 {
1601			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1602		} else {
1603			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1604			for i, ev := range shown {
1605				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1606			}
1607		}
1608		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1609			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1610	}
1611	
1612	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1613	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1614	// 说明汇款总额与本账单分配。
1615	func formatLedgerEvent(ev ledgerEvent) string {
1616		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1617			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1618		switch ev.kind {
1619		case "调整":
1620			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1621				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1622		case "撤销调整":
1623			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1624				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1625		case "收款":
1626			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1627				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1628		case "更正":
1629			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1630				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1631		default: // 撤销收款
1632			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1633				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1634		}
1635	}
1636

