289	// settleTiered 对绑定阶梯方案的客户按 UTC 自然月累计用量分档计价并封账。
290	// recs 已按计价顺序（时间点升序、同一时间按标识字典序）排列；有效方案
291	// 月费大于 0 时 recs 可为空（无用量也须出账收取整月月费）。
292	// 月累计数量、分档金额或月费加全月用量费溢出时拒绝结算且不封账。
293	func settleTiered(s *state, cust *customer, month string, recs []*usageRecord) error {
294		b, err := buildTieredBill(s, cust, month, recs)
295		if err != nil {
296			return fmt.Errorf("客户 %s 的 %s 阶梯计价失败，拒绝结算且不封账: %w", cust.ID, month, err)
297		}
298		key := billKey(cust.ID, month)
299		s.Bills[key] = b
300	
301		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
302		if err := s.save(); err != nil {
303			delete(s.Bills, key)
304			return err
305		}
306		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账（阶梯计费）：\n\n", cust.ID, month)
307		printBill(b, cust, s)
308		return nil
309	}
310	
311	// buildTieredBill 为绑定阶梯方案的客户构造阶梯账单（不落盘）：采用账期月的
312	// 有效方案（初始绑定被生效月不晚于账期月的最后一次变更替换）从零累计分档
313	// 计价，账单保存方案标识、名称、完整规则与实际月费快照。recs 须已按计价
314	// 顺序排列；有效方案月费大于 0 时 recs 可为空。原总金额 = 月费 + 全月
315	// 用量费；月累计数量、分档金额或月费加全月用量费溢出时返回错误。
316	func buildTieredBill(s *state, cust *customer, month string, recs []*usageRecord) (*bill, error) {
317		p := s.Plans[s.effectivePlanID(cust, month)] // 载入时已校验存在
318		priced, err := tieredPrice(p.Tiers, recs)
319		if err != nil {
320			return nil, err
321		}
