		t.Fatalf("账单方案与账期安排不一致未报损坏: %s", msg)
	}
	// 恢复完好存档后一切正常。
	if err := os.WriteFile(h.statePath(), good, 0o644); err != nil {
		t.Fatal(err)
	}
	h.mustRun("plan", "schedule", "c1")
	h.mustRun("bill", "show", "c1", "2026-11")
}

